// DEMO SOURCE so the template runs immediately. For production, disable
// this node and read appointments from Google Sheets (columns listed here).
const demoRows = [
  { appointment_id: 'APT-1041', customer_name: 'Anna de Vries', phone: '+316****5678', email: 'user@example.com', starts_at: new Date(Date.now() + 2 * 3600 * 1000).toISOString(), practitioner: 'Lisa', treatment: 'Haircut', channel_preference: 'whatsapp', status: 'unconfirmed', prior_no_shows: 0 },
  { appointment_id: 'APT-1042', customer_name: 'Mark Jansen', phone: '+316****5432', email: 'user@example.com', starts_at: new Date(Date.now() + 20 * 3600 * 1000).toISOString(), practitioner: 'Dr. Bakker', treatment: 'Check-up', channel_preference: 'email', status: 'unconfirmed', prior_no_shows: 1 },
  { appointment_id: 'APT-1043', customer_name: 'Fatima El Amrani', phone: '+316****3344', email: 'user@example.com', starts_at: new Date(Date.now() + 60 * 3600 * 1000).toISOString(), practitioner: 'Lisa', treatment: 'New client', channel_preference: 'whatsapp', status: 'confirmed', prior_no_shows: 0 },
  { appointment_id: 'APT-1044', customer_name: 'Tom Willems', phone: '+316****5645', email: 'user@example.com', starts_at: new Date(Date.now() - 30 * 60 * 1000).toISOString(), practitioner: 'Emma', treatment: 'Balayage', channel_preference: 'whatsapp', status: 'no_show', prior_no_shows: 2 }
];
return demoRows.map((row) => ({ json: row }));

// Pick the reminder stage for each appointment and deduplicate with
// workflow static data: each appointment gets each stage at most once,
// even if the schedule fires several times inside a band.
// Bands: heads_up 48-72h, confirm_ask 8-48h, same_day 0.5-3h before start.
const BANDS = [
  { stage: 'heads_up', minH: 48, maxH: 72 },
  { stage: 'confirm_ask', minH: 8, maxH: 48 },
  { stage: 'same_day', minH: 0.5, maxH: 3 }
];
const staticData = $getWorkflowStaticData('global');
staticData.sent = staticData.sent || {};
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const h = (new Date(r.starts_at).getTime() - now) / 3600000;
  if (h < 0) continue; // already started
  for (const b of BANDS) {
    if (h >= b.minH && h < b.maxH) {
      const key = r.appointment_id + ':' + b.stage;
      if (staticData.sent[key]) break;
      staticData.sent[key] = new Date().toISOString();
      const dateStr = new Date(r.starts_at).toLocaleString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });
      let message;
      if (b.stage === 'same_day') {
        message = 'Hi ' + r.customer_name + ', your ' + r.treatment + ' with ' + r.practitioner + ' is today at ' + dateStr + '. See you soon!';
      } else if (b.stage === 'confirm_ask') {
        message = 'Hi ' + r.customer_name + ', reminder: your ' + r.treatment + ' with ' + r.practitioner + ' is on ' + dateStr + '. Reply CONFIRM to keep it or RESCHEDULE to move it.';
      } else {
        message = 'Hi ' + r.customer_name + ', you are booked for ' + r.treatment + ' with ' + r.practitioner + ' on ' + dateStr + '. Need a different time? Reply RESCHEDULE.';
      }
      out.push({ json: {
        appointment_id: r.appointment_id,
        customer_name: r.customer_name,
        to: r.channel_preference === 'email' ? r.email : r.phone,
        channel: r.channel_preference === 'email' ? 'email' : 'whatsapp',
        stage: b.stage,
        hours_until: Math.round(h * 10) / 10,
        message: message
      }});
      break;
    }
  }
}
return out;

// Placeholder for your real send node (WhatsApp Business Cloud, SMS or
// email). Same-day items arrive here; they can take a priority lane.
const items = $input.all();
return items.map((item) => ({ json: { ...item.json, sent_at: new Date().toISOString(), transport: 'demo', lane: 'same_day' } }));

// Placeholder for your real send node (WhatsApp Business Cloud, SMS or
// email) for the earlier reminder stages.
const items = $input.all();
return items.map((item) => ({ json: { ...item.json, sent_at: new Date().toISOString(), transport: 'demo', lane: 'staged' } }));

// Classify an inbound customer reply. Expected body (WhatsApp-style):
// appointment_id (add it to your quick-reply link or lookup by From),
// From, Body. English and Dutch keywords.
const b = $input.first().json.body || $input.first().json;
const text = String(b.Body || b.text || '').trim().toUpperCase();
let verdict = 'no_reply';
if (/^(JA|J|YES|Y|OK|CONFIRM|C)([\s!.,]|$)/.test(text)) verdict = 'confirmed';
else if (/^(NEE|N|NO|RESCHEDULE|CANCEL|WIJZIG)([\s!.,]|$)/.test(text)) verdict = 'cancel_requested';
else if (text) verdict = 'unclear';
return [{ json: {
  appointment_id: b.appointment_id || '',
  from: b.From || b.from || '',
  raw_text: text,
  verdict: verdict,
  received_at: new Date().toISOString()
} }];

// Placeholder: mark the appointment confirmed in your sheet or calendar.
const items = $input.all();
return items.map((item) => ({ json: { ...item.json, action: 'mark_confirmed', logged_at: new Date().toISOString() } }));

// DEMO lookup of the cancelled appointment's slot. For production,
// replace with a Google Sheets or calendar lookup on appointment_id.
const cls = $('Classify reply').first().json;
const rows = [
  { appointment_id: 'APT-1041', slot_start: new Date(Date.now() + 2 * 3600 * 1000).toISOString(), practitioner: 'Lisa', treatment: 'Haircut', duration_min: 45 },
  { appointment_id: 'APT-1042', slot_start: new Date(Date.now() + 20 * 3600 * 1000).toISOString(), practitioner: 'Dr. Bakker', treatment: 'Check-up', duration_min: 30 }
];
const hit = rows.find((r) => r.appointment_id === cls.appointment_id);
return [{ json: { ok: !!hit, ...(hit || rows[0]) } }];

// DEMO SOURCE. Replace with your waitlist sheet.
// Columns: customer_name, phone, wanted_treatment, flexible (bool), priority_score
const demoWaitlist = [
  { customer_name: 'Lisa Mertens', phone: '+316****5641', wanted_treatment: 'Haircut', flexible: true, priority_score: 9 },
  { customer_name: 'Daan Cox', phone: '+316****5642', wanted_treatment: 'Balayage', flexible: false, priority_score: 6 },
  { customer_name: 'Nina Blaauw', phone: '+316****5643', wanted_treatment: 'Haircut', flexible: true, priority_score: 7 }
];
return demoWaitlist.map((row) => ({ json: row }));

// Rank the waitlist for the freed slot: treatment match first, flexible
// entries next, then priority score. Top 3 get an offer at once; first
// TAKE wins, the rest get a friendly note.
const slot = $('Load slot details (demo)').first().json;
const items = $('Waitlist (demo data)').all();
const ranked = items
  .map((item) => {
    const r = item.json;
    let score = 0;
    if (slot.treatment && r.wanted_treatment === slot.treatment) score += 50;
    if (r.flexible) score += 20;
    score += Number(r.priority_score) || 0;
    return { json: { ...r, match_score: score } };
  })
  .sort((a, b) => b.json.match_score - a.json.match_score)
  .slice(0, 3);
const slotStr = new Date(slot.slot_start).toLocaleString('en-GB', { weekday: 'long', hour: '2-digit', minute: '2-digit' });
return ranked.map((entry, i) => ({ json: {
  ...entry.json,
  offer_position: i + 1,
  slot_start: slot.slot_start,
  freed_appointment: slot.appointment_id,
  message: 'Hi ' + entry.json.customer_name + ', a spot just opened up ' + slotStr + ' with ' + slot.practitioner + '. You are on our waitlist. Want this spot? Reply TAKE within 30 minutes, after that it goes to the next person.'
} }));

// Placeholder for your real send node (WhatsApp Business Cloud / SMS).
const items = $input.all();
return items.map((item) => ({ json: { ...item.json, sent_at: new Date().toISOString(), transport: 'demo' } }));

// Placeholder: queue the unclear reply or silence for staff follow-up.
const items = $input.all();
return items.map((item) => ({ json: { ...item.json, action: 'staff_followup', logged_at: new Date().toISOString() } }));
